// Renders the reference page in docs/format from the JSON Schema of the .vellum document (guide Prompt 8).
// Pure: the same schema always gives the same Markdown. Nothing here reads the clock, the environment or the
// file system, and definitions are written in name order, so the page can be checked for drift.

const BANNER =
  "Generated from `crates/vellum-types` by `scripts/gen-format.mjs`. Do not edit this file: run `pnpm format-spec:gen`.";

const refName = (ref) => ref.slice(ref.lastIndexOf("/") + 1);
const link = (name) => `[${name}](#${name.toLowerCase()})`;
const cell = (text) => (text ?? "").replace(/\s+/g, " ").replace(/\|/g, "\\|").trim();
const quoted = (value) => JSON.stringify(value);
const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);

/** The schema's type, for a table cell: a link for a named definition, otherwise a plain description. */
export function typeOf(schema) {
  if (!isObject(schema)) return "any";
  if (schema.$ref) return link(refName(schema.$ref));
  if (schema.enum) {
    return schema.enum.length === 1
      ? quoted(schema.enum[0])
      : `one of ${schema.enum.map(quoted).join(", ")}`;
  }
  if (schema.const !== undefined) return quoted(schema.const);
  const alternatives = schema.anyOf ?? schema.oneOf;
  if (alternatives) {
    // `null` marks an optional value; the Required column already says whether it must be given.
    const parts = [...new Set(alternatives.map(typeOf))].filter((part) => part !== "null");
    return parts.length ? parts.join(" or ") : "null";
  }
  if (schema.allOf) return typeOf(schema.allOf[0]);
  if (Array.isArray(schema.type)) {
    const kinds = schema.type.filter((kind) => kind !== "null");
    return kinds.length ? kinds.join(" or ") : "null";
  }
  if (schema.type === "array") return `array of ${typeOf(schema.items)}`;
  if (schema.type === "object" && isObject(schema.additionalProperties)) {
    const keys = isObject(schema.propertyNames) ? typeOf(schema.propertyNames) : "string";
    return `map from ${keys} to ${typeOf(schema.additionalProperties)}`;
  }
  return schema.type ?? "any";
}

/** A list item: the type, then the variant's own description when it has one. */
const bullet = (text, schema) =>
  `- ${text}${schema.description ? `. ${cell(schema.description)}` : ""}`;

/** One variant of a union, with the fields its own schema and any `allOf` references add. */
function flatten(variant, defs) {
  const merged = { description: variant.description, properties: {}, required: [] };
  const absorb = (part) => {
    if (part.$ref) {
      absorb(defs[refName(part.$ref)] ?? {});
      return;
    }
    if (part.description && !merged.description) merged.description = part.description;
    Object.assign(merged.properties, part.properties ?? {});
    merged.required.push(...(part.required ?? []));
    for (const inner of part.allOf ?? []) absorb(inner);
  };
  absorb(variant);
  return merged;
}

function fieldTable(properties, required, skip, defs) {
  const rows = Object.entries(properties)
    .filter(([name]) => name !== skip)
    .map(([name, prop]) => {
      const text = prop.description ?? (prop.$ref ? defs[refName(prop.$ref)]?.description : "");
      return `| \`${name}\` | ${typeOf(prop)} | ${required.includes(name) ? "yes" : "no"} | ${cell(text)} |`;
    });
  if (rows.length === 0) return [];
  return ["| Property | Type | Required | Description |", "|---|---|---|---|", ...rows, ""];
}

/** A definition that is a union: tagged variants get a table of their fields, the rest a bullet. */
function unionLines(alternatives, defs) {
  const lines = [];
  for (const variant of alternatives) {
    const flat = flatten(variant, defs);
    const tag = Object.entries(flat.properties).find(([, prop]) => prop.const !== undefined);
    const description = cell(flat.description);
    if (tag) {
      const [tagName, tagSchema] = tag;
      lines.push(`#### \`${tagSchema.const}\``, "");
      if (description) lines.push(description, "");
      lines.push(...fieldTable(flat.properties, flat.required, tagName, defs));
      continue;
    }
    // An externally tagged variant has one key, the name of its payload.
    const keys = Object.keys(flat.properties);
    if (keys.length === 1 && flat.required.includes(keys[0])) {
      const [key] = keys;
      const suffix = description ? `. ${description}` : "";
      lines.push(`- \`${key}\`: ${typeOf(flat.properties[key])}${suffix}`);
      continue;
    }
    lines.push(bullet(typeOf(variant), variant));
  }
  return lines.length ? [...lines, ""] : [];
}

/** What a schema says, under its heading: its description, then its fields, variants or type. */
function bodyLines(schema, defs) {
  const lines = [];
  if (schema.description) lines.push(schema.description, "");
  if (schema.oneOf) lines.push(...unionLines(schema.oneOf, defs));
  else if (schema.anyOf) {
    lines.push(
      "One of:",
      "",
      ...schema.anyOf.map((variant) => bullet(typeOf(variant), variant)),
      "",
    );
  } else if (schema.properties) {
    lines.push(...fieldTable(schema.properties, schema.required ?? [], undefined, defs));
  } else {
    lines.push(`Type: ${typeOf(schema)}`, "");
  }
  return lines;
}

/** The reference page for the document schema: the document, then every named definition in name order. */
export function renderFormatSpec(schema) {
  const defs = schema.$defs ?? {};
  const root = { ...schema };
  delete root.$defs;
  const lines = ["# The .vellum format", "", BANNER, "", "## Document", ""];
  lines.push(...bodyLines(root, defs));
  lines.push("## Definitions", "");
  for (const name of Object.keys(defs).sort()) {
    lines.push(`### ${name}`, "", ...bodyLines(defs[name], defs));
  }
  return `${lines
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trimEnd()}\n`;
}
